"""Build the dashboard and a single-flash factory image with populated LittleFS."""
Import("env")
import importlib.util
from pathlib import Path
import subprocess
import sys
from SCons.Script import DefaultEnvironment

project_dir = Path(env.subst("$PROJECT_DIR"))
subprocess.run(["node", str(project_dir / "usermods/inter_comms_ui/build_ui.mjs")], cwd=project_dir, check=True)


def load_module(name, path):
    """Load project helpers and the framework's authoritative partition-table parser."""
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def runtime_config_path(env):
    """Locate the SDK configuration actually selected for this target and memory type."""
    board = env.BoardConfig()
    framework = Path(env.PioPlatform().get_package_dir("framework-arduinoespressif32"))
    return (framework / "tools/esp32-arduino-libs" / board.get("build.mcu") /
            board.get("build.arduino.memory_type", "qio_qspi") / "include/sdkconfig.h")


def build_factory(source, target, env):
    """Merge platform boot images, application and a verified filesystem at their partition offsets."""
    platform = env.PioPlatform()
    framework = Path(platform.get_package_dir("framework-arduinoespressif32"))
    parser = load_module("factory_partitions", framework / "tools/gen_esp32part.py")
    helpers = load_module("factory_image", project_dir / "usermods/inter_comms_ui/factory_image.py")
    board = env.BoardConfig()
    flash_size = str(board.get("upload.flash_size", "8MB"))
    flash_bytes = int(flash_size.removesuffix("MB")) * 1024 * 1024
    build_dir = Path(env.subst("$BUILD_DIR"))
    partitions = parser.PartitionTable.from_binary((build_dir / "partitions.bin").read_bytes())
    partitions.verify()
    partitions.verify_size_fits(flash_bytes)
    app = next(partitions.find_by_type("app", "ota_0"), None)
    fs = partitions.find_by_name("spiffs")
    if app is None or fs is None or fs.type != parser.DATA_TYPE or fs.subtype != 0x82:
        raise ValueError("Factory image requires an OTA application and the existing LittleFS partition")
    firmware = Path(str(source[0]))
    if firmware.stat().st_size > app.size:
        raise ValueError("Application image exceeds its OTA partition")
    filesystem = build_dir / "model-filesystem.bin"
    fs_config = helpers.read_runtime_config(runtime_config_path(env))
    version = fs_config["disk_version"]
    print(f"Factory LittleFS: target disk version {version >> 16}.{version & 0xffff}, cache {fs_config['cache_size']} bytes")
    filesystem.write_bytes(helpers.build_filesystem(project_dir / "build_output/inter-comms-assets", fs.size, fs_config))
    output = Path(str(target[0]))
    output.parent.mkdir(parents=True, exist_ok=True)
    segments = [(int(str(offset), 0), Path(env.subst(str(path)))) for offset, path in env.get("FLASH_EXTRA_IMAGES", [])]
    if not any(path.name == "partitions.bin" for _, path in segments) or not any(offset == 0 for offset, _ in segments):
        raise ValueError("Factory image is missing the platform bootloader or partition table")
    segments.extend([(app.offset, firmware), (fs.offset, filesystem)])
    segments.sort()
    frequency = str(int(str(board.get("build.f_flash", "80000000L")).rstrip("L")) // 1000000) + "m"
    command = [sys.executable, "-m", "esptool", "--chip", board.get("build.mcu"), "merge-bin",
               "--flash-mode", board.get("build.flash_mode", "qio"), "--flash-freq", frequency,
               "--flash-size", flash_size, "--pad-to-size", flash_size, "-o", str(output)]
    for offset, path in segments:
        command.extend([hex(offset), str(path)])
    subprocess.run(command, cwd=project_dir, check=True)
    merged = output.read_bytes()
    if len(merged) != flash_bytes or merged[app.offset:app.offset + firmware.stat().st_size] != firmware.read_bytes():
        raise ValueError("Factory image application placement verification failed")
    if merged[fs.offset:fs.offset + fs.size] != filesystem.read_bytes():
        raise ValueError("Factory image filesystem placement verification failed")
    print(f"Factory image: {output} (flash at 0x0; includes all model files)")


def upload_factory(source, target, env):
    """Flash the complete factory image in one serial operation; existing settings are reset."""
    protocol = env.subst("$UPLOAD_PROTOCOL") or "esptool"
    if protocol != "esptool":
        raise ValueError("uploadfactory requires a serial esptool upload; factory images are not OTA firmware")
    env.AutodetectUploadPort()
    port = env.subst("$UPLOAD_PORT")
    if not port or "." in port and not port.startswith(("/", "\\")):
        raise ValueError("uploadfactory requires a serial port, not a network address")
    print("Factory installation replaces the filesystem and resets saved device settings.")
    subprocess.run([sys.executable, "-m", "esptool", "--chip", env.BoardConfig().get("build.mcu"),
                    "--port", port, "--baud", env.subst("$UPLOAD_SPEED"),
                    "write-flash", "0x0", str(source[0])], cwd=project_dir, check=True)


# Register on the project environment so standard builds include the factory artifact.
project_env = DefaultEnvironment()
build_dir = Path(project_env.subst("$BUILD_DIR"))
assets_dir = project_dir / "build_output/inter-comms-assets"
factory = project_env.Command(
    str(project_dir / "build_output/release" / (project_env["PIOENV"] + ".factory.bin")),
    [str(build_dir / (project_env.subst("${PROGNAME}") + ".bin")), str(build_dir / "partitions.bin"),
     str(assets_dir / "manifest.json"), str(project_dir / "usermods/inter_comms_ui/factory_image.py"),
     str(project_dir / "usermods/inter_comms_ui/build.py"), str(runtime_config_path(project_env))] +
    [str(path) for path in sorted((assets_dir / "inter_comms").glob("*.webp"))],
    project_env.VerboseAction(build_factory, "Building single-flash factory image with model files"),
)
project_env.Alias("buildprog", factory)
project_env.AddCustomTarget("uploadfactory", factory,
    project_env.VerboseAction(upload_factory, "Flashing factory image (resets saved settings)"),
    title="Upload factory image", description="Flash firmware and model files together; resets saved settings")
